SELECT task.task_type, task.product_line ->> '$.id' as product_line, task.class_time, task.classes_id as classId, task.class_group_id, info.destory_start_time, info.destory_end_time, info.destory_reason, info.destory_work_station FROM qt_check_task_destory_info info JOIN qt_check_task task ON info.task_id = task.id WHERE info.del_flag = 0 AND task.del_flag = 0 AND task.status = 2 AND task.task_type IN ( 3, 4 ) AND info.destory_reason IS NOT NULL AND task.product_line ->> '$.id' IN
#{item}
AND ((task.defect_start_time >= #{start} and task.defect_start_time < #{end}) OR (task.finished_time >= #{start} and task.finished_time < #{end} ))
